Definition st0c_chk (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  match t with
  | CC.TOther pc =>
      if (Nat.eqb i I_ENTRY && Nat.eqb (PSM5.ng_of pc) 5)%bool then
        match CH2.ret_of G.RETS i k with
        | Some j =>
            match kind_of j with
            | KPt => (PSYK.adm_all 42 (SR.ps_cells ps) 0 256 (fun st => negb (st =? PML.ST_ACCEPT)) ||
                      PSYK.adm_all 42 (SR.ps_cells ps) 0 256 (fun st => PSYK.adm_all 44 (SR.ps_cells ps) 0 8 (fun nst => negb (st =? PML.ST_ACCEPT))))%bool
            | _ => true
            end
        | None => true
        end
      else true
  | _ => true
  end.

Definition ptx_chk (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  match t with
  | CC.TOther pc =>
      if Nat.eqb (PSM5.ng_of pc) 5 then
        match CH2.ret_of G.RETS i k with
        | Some j => (Nat.leb (APC.NCS + 5) (CC.cp_nx (PSM2.cutn j)) && implb (PSM2.in_loop j) (PSM2.in_loop i) &&
                     forallb (fun x : expr * expr => (APC.expr_vars_lt (CC.cp_nx c) (fst x) && APC.expr_vars_lt (CC.cp_nx c) (snd x))%bool) (nth i G.BLS []))%bool
        | None => true
        end
      else true
  | _ => true
  end.
Lemma st0c_ok : CH2.leaves_all G.CPS G.TAGS st0c_chk = true.
Proof. vm_compute. reflexivity. Qed.
Lemma ptx_ok : CH2.leaves_all G.CPS G.TAGS ptx_chk = true.
Proof. vm_compute. reflexivity. Qed.
