Definition src_ok (i : nat) (pv lv : PB4.pvals2) (d : PSM2.delta) (cls : PSM6.dcls) (E1 E' : env) (M' : mem) (pst : PML.pstate) : Prop :=
    PML.parser_at M' P pst /\ PML.wf_ps pst /\ PML.buf_bound pst B /\ PML.ps_more pst = true /\
    PML.ps_st pst = uv E' (PB4.pv_st lv) /\ PML.ps_nst pst = uv E' (PB4.pv_nst lv) /\ PML.ps_win pst = PB4.win_of (uv E' (PB4.pv_wptr lv)) wend /\
    seg <= uv E' (PB4.pv_wptr lv) <= wend /\ uv E' (PB4.pv_wptr lv) = uv E1 (PB4.pv_wptr pv) + PSM2.d_adv d /\ 0 <= PSM2.d_adv d <= 1 /\
    CH2.den E1 (nth i G.BLS []) = PML.ps_blocks pst /\ PML.ls_ok g M' /\ PSIU.xsync pst eg /\      (* [comment removed for export] *)
    match cls with
    | PSM6.D0 => uv E' (PB4.pv_st lv) = uv E' (PB4.pv_st pv) /\ ((i = I_HLO \/ i = I_HHI \/ i = I_HN \/ i = I_L \/ i = I_HS) -> PSIU.RANK pst <= bv_unsigned (ev E1 54)) /\ PB4.pv_nst lv = PB4.pv_nst pv
    | PSM6.D3 _ => uv E' (PB4.pv_st lv) = 17
    | _ => uv E' (PB4.pv_st lv) = 15
    end.
