Lemma post_sync : forall j pst ps2 code E2 (M2 : mem) cur, PSM2.cur_cut j = false -> PML.parser_at M2 P ps2 -> PML.ps_win pst = PB4.win_of cur wend -> seg <= cur <= wend ->
  (PSIU.skip_cut j = true -> code = 0) ->
  (code = 0 -> PMS.not_retreated pst ps2 /\ PML.ps_more ps2 = true /\ (PSM2.under0 j = true -> In (PML.ps_st ps2) [PML.ST_ACCEPT; PML.ST_EXPECT_COMMA_OR_END]) /\
               (PSM2.in_loop j = true -> if Z.eqb (PSM2.reent_pc j) L2PC then PML.winlen ps2 = bv_unsigned (ev E2 53)
