Lemma post_cur : forall j pst ps2 code E2 (M2 : mem) R2 cur, PSM2.cur_cut j = true -> PML.parser_at M2 P (PML.ps_set_win ps2 (PML.ps_win pst)) -> PML.ps_win pst = PB4.win_of cur wend -> seg <= cur <= wend -> wend <> 0 ->
  PMS.not_retreated pst ps2 -> (exists p e, PML.ps_win ps2 = Some (p, e) /\ PML.a0 R2 p) -> ev E2 (CC.cp_nx (PSM2.cutn j) - APC.NCS + 4) = getr R2 10%bv ->
  (PSIU.skip_cut j = true -> code = 0) ->
  (code = 0 -> PML.ps_more ps2 = true /\ (PSM2.under0 j = true -> In (PML.ps_st ps2) [PML.ST_ACCEPT; PML.ST_EXPECT_COMMA_OR_END]) /\
               (PSM2.in_loop j = true -> if Z.eqb (PSM2.reent_pc j) L2PC then PML.winlen ps2 = bv_unsigned (ev E2 53)
