Lemma st0_entry : forall c k ps1 pc j E' R' (M1 M' : mem), is_leaf I_ENTRY c k ps1 (CC.TOther pc) -> PSM5.ng_of pc = 5%nat ->
  CH2.ret_of G.RETS I_ENTRY k = Some j -> kind_of j = KPt ->
  env_agree GT.NF E0 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' -> st0 <> PML.ST_ACCEPT.
Proof.
  intros c k ps1 pc j E' R' M1 M' IL Hng Hret Hkj Hag LF.
  pose proof (CH2.leaves_all_sound G.CPS G.TAGS st0c_chk st0c_ok I_ENTRY c k ps1 (CC.TOther pc) IL) as H.
  unfold st0c_chk in H. cbv beta iota in H. rewrite Nat.eqb_refl, Hng in H. cbn [andb Nat.eqb] in H.
  rewrite Hret in H. cbv beta iota in H. rewrite Hkj in H. cbv beta iota in H.
  assert (HK : know_ok RSEGS E' M' (SR.ps_cells ps1)) by (first [exact (PSBU.leaf_know I c ps1 E' R' M1 M' LF) | exact (PSBU.leaf_know I eg c ps1 E' R' M1 M' LF) | exact (PSBU.leaf_know I eg M0c c ps1 E' R' M1 M' LF) | exact (PSBU.leaf_know I eg M0c OKV c ps1 E' R' M1 M' LF)]).
  assert (U42 : bv_unsigned (ev E0 42) = st0) by (pose proof (PSIU.UU I); tauto).
  assert (U44 : bv_unsigned (ev E0 44) = PSIU.nst0 I) by (pose proof (PSIU.UU I); tauto).
  assert (Hr : 1 <= st0 <= 28) by (pose proof (PSIU.NUM I); tauto).
  assert (Hn : 0 <= PSIU.nst0 I <= 7) by (pose proof (PSIU.NUM I); tauto).
  pose proof Hag as [HagV _].
  assert (HE : ev E' 42 = Z_to_bv 64 st0).
  { rewrite <- (HagV 42%nat ltac:(pose proof S2LT; lia)). rewrite <- U42. symmetry. apply Z_to_bv_bv_unsigned. }
  assert (HE4 : ev E' 44 = Z_to_bv 64 (PSIU.nst0 I)).
  { rewrite <- (HagV 44%nat ltac:(pose proof S2LT; lia)). rewrite <- U44. symmetry. apply Z_to_bv_bv_unsigned. }
  pose proof (RLF.byte_adm_sound RSEGS 42 E' M' st0 _ HK HE) as HA.
  pose proof (RLF.byte_adm_sound RSEGS 44 E' M' (PSIU.nst0 I) _ HK HE4) as HA4.
  intros X.
  apply orb_prop in H as [H|H]; unfold PSYK.adm_all in H;
    pose proof (RLF.forall_b_sound 256 0 _ st0 H ltac:(change (Z.of_nat 256) with 256; lia)) as HF; cbv beta in HF; rewrite HA in HF; cbn [negb orb] in HF.
  - rewrite X in HF. vm_compute in HF. discriminate HF.
  - unfold PSYK.adm_all in HF. pose proof (RLF.forall_b_sound 8 0 _ (PSIU.nst0 I) HF ltac:(change (Z.of_nat 8) with 8; lia)) as HF2.
    cbv beta in HF2. rewrite HA4 in HF2. cbn [negb orb] in HF2. rewrite X in HF2. vm_compute in HF2. discriminate HF2.
Qed.
Section PT.
(* [comment removed for export] *)
Variables (f : PMW.fname) (WFin : PML.pstate -> Prop) (BBin : PML.pstate -> Z -> Prop) (PAin : mem -> Z -> PML.pstate -> Prop) (PAout : PML.pstate -> mem -> Z -> PML.pstate -> Prop).
Variables (CPC CSCR : Z) (Args : bvmap 5 word -> mem -> Z -> Z -> Z -> PML.pstate -> list Z -> Prop) (Rel : PML.pstate -> PML.pstate -> Z -> bvmap 5 word -> Prop).
Hypothesis CALLEE : PMW.ptrans_gbw L HI PMR.the_rm f (PMW.rm_match PMR.the_rm) PMW.inp_win WFin BBin PAin PAout CPC CSCR Args Rel.
Hypothesis PAOUT_CAP : forall pst (M1 : mem) P1 ps2, PAout pst M1 P1 ps2 -> PML.ps_bcap ps2 mod 2 = 0.
Hypothesis FPMS : f = PMW.FSkipSpace \/ f = PMW.FBeginMember.

Lemma pt_leaf0 : forall ereg i c k ps1 j cj ci pv lv pe ce d cls,
  is_leaf i c k ps1 (CC.TOther CPC) -> CH2.ret_of G.RETS i k = Some j -> nth_error G.CPS j = Some cj -> SR.ps_pc ps1 = CPC -> PSM5.ng_of CPC = 5%nat ->
  PB2.ptrans_chk GT.NF G.HDECL Eb 0 Pb 0 CSCR ereg c ps1 cj (nth i G.BLS []) (nth j G.BLS []) = Some ci ->
  PSM2.ldelta i c ps1 = Some (pv, lv, pe, ce, d) -> PSM6.dclass i c ps1 pv lv d = Some cls -> kind_of j = KPt -> PSM2.rng_is (SR.ps_cells ps1) (PB4.pv_more pv) 1 = true ->
  PB.has (SR.ps_cells ps1) (KWord (SA Vb 0) 8 (ELit PML.VT_VISITOR)) = true -> PB.has (SR.ps_cells ps1) (KWord (SA Eb 0) 4 (ELit 0)) = true ->
  (forall E1 E' R' (M1 M' : mem) model1 pst, env_agree GT.NF E0 E' -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' -> regs_ok E' (CA.ps_reglist ps1) R' ->
     HAMB i E1 M' model1 -> XI i E1 M1 -> SIM i E1 M1 -> src_ok i pv lv d cls E1 E' M' pst ->
     exists (w' : list Z) (c' : PMR.ctrl),
     (PMW.win_bytes M' pst w' /\ PMR.rm_match c' M' P pst /\ PSYJU.WCONT I eg f j pst w' c') /\
     Args R' M' P V E pst [] /\ PAin M' P pst /\ WFin pst /\ BBin pst B /\
     forall R2 (M2 : mem) ps2 code E2, PAout pst M2 P ps2 -> PML.wf_ps ps2 -> (code <> 0 -> PML.ps_more ps2 = false) -> Rel pst ps2 code R2 ->
        PML.win_ok M2 LBr ps2 ->      (* [comment removed for export] *)
        env_agree (CC.cp_nx cj - APC.NCS - 5) E' E2 -> ev E2 (CC.cp_nx cj - APC.NCS + 4) = getr R2 10%bv ->
        (code = 0 -> PMR.rm_match (PMW.r_ctrl (PMR.rstep f c' w')) M2 P ps2) ->      (* [comment removed for export] *)
