Qed.
Lemma pt_leaf : forall ereg i c k ps1 j cj ci pv lv pe ce d cls,
  is_leaf i c k ps1 (CC.TOther CPC) -> CH2.ret_of G.RETS i k = Some j -> nth_error G.CPS j = Some cj -> SR.ps_pc ps1 = CPC -> PSM5.ng_of CPC = 5%nat ->
  PB2.ptrans_chk GT.NF G.HDECL Eb 0 Pb 0 CSCR ereg c ps1 cj (nth i G.BLS []) (nth j G.BLS []) = Some ci ->
  PSM2.ldelta i c ps1 = Some (pv, lv, pe, ce, d) -> PSM6.dclass i c ps1 pv lv d = Some cls -> kind_of j = KPt -> PSM2.rng_is (SR.ps_cells ps1) (PB4.pv_more pv) 1 = true ->
  PB.has (SR.ps_cells ps1) (KWord (SA Vb 0) 8 (ELit PML.VT_VISITOR)) = true -> PB.has (SR.ps_cells ps1) (KWord (SA Eb 0) 4 (ELit 0)) = true ->
  (forall E1 E' R' (M1 M' : mem) model1 pst, env_agree GT.NF E0 E' -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' -> regs_ok E' (CA.ps_reglist ps1) R' ->
     HAMB i E1 M' model1 -> XI i E1 M1 -> SIM i E1 M1 -> src_ok i pv lv d cls E1 E' M' pst ->
     exists (w' : list Z) (c' : PMR.ctrl),
     (PMW.win_bytes M' pst w' /\ PMR.rm_match c' M' P pst /\ PSYJU.WCONTY I eg f j pst w' c') /\
     Args R' M' P V E pst [] /\ PAin M' P pst /\ WFin pst /\ BBin pst B /\
     forall R2 (M2 : mem) ps2 code E2, PAout pst M2 P ps2 -> PML.wf_ps ps2 -> (code <> 0 -> PML.ps_more ps2 = false) -> Rel pst ps2 code R2 ->
        PML.win_ok M2 LBr ps2 ->
        env_agree (CC.cp_nx cj - APC.NCS - 5) E' E2 -> ev E2 (CC.cp_nx cj - APC.NCS + 4) = getr R2 10%bv ->
        (code = 0 -> PMR.rm_match (PMW.r_ctrl (PMR.rstep f c' w')) M2 P ps2) ->
        (code = 0 -> PMS.not_retreated pst ps2) /\ post_ok j ps2 code E2 M2 /\ (code = 0 -> PSIU.xsync ps2 eg) /\ PML.win_ok M2 LBo ps2) ->
  CC.leaf_ok (hl_segs L) G.CPS AMB3 K PML.fp_ok i c ps1.
Proof.
  intros ereg i c k ps1 j cj ci pv lv pe ce d cls H1 H2 H3 H4 H5 H6 H7 H8 H9 H10 H11 H12 USER.
  apply (pt_leaf0 ereg i c k ps1 j cj ci pv lv pe ce d cls H1 H2 H3 H4 H5 H6 H7 H8 H9 H10 H11 H12).
  intros E1 E' R' M1 M' model1 pst A1 A2 A3 A4 A5 A6 A7 A8.
  destruct (USER E1 E' R' M1 M' model1 pst A1 A2 A3 A4 A5 A6 A7 A8) as (w' & c' & (HWB & HRM & HW & _) & REST).
  exists w', c'. exact (conj (conj HWB (conj HRM HW)) REST).
Qed.
End PT.

