Section PTX.
(* [comment removed for export] *)
Variables (f : PMW.fname) (isbuf : bool) (MIn : PMR.ctrl -> mem -> Z -> PML.pstate -> Prop).
Let inp : PML.pstate -> list Z -> list Z -> list Z := if isbuf then PMW.inp_buf else PMW.inp_win.
Variables (WFin : PML.pstate -> Prop) (BBin : PML.pstate -> Z -> Prop) (PAin : mem -> Z -> PML.pstate -> Prop) (PAout : PML.pstate -> mem -> Z -> PML.pstate -> Prop).
Variables (CPC CSCR : Z) (Args : bvmap 5 word -> mem -> Z -> Z -> Z -> PML.pstate -> list Z -> Prop) (Rel : PML.pstate -> PML.pstate -> Z -> bvmap 5 word -> Prop).
Hypothesis CALLEE : PMW.ptrans_gbxwU L HI PMR.the_rm f MIn inp WFin BBin PAin PAout CPC CSCR Args Rel.
Hypothesis MIN : forall c' (Mx : mem) P1 pst, PMR.rm_match c' Mx P1 pst -> MIn c' Mx P1 pst.
Hypothesis PAOUT_CAP : forall pst (M1 : mem) P1 ps2, PAout pst M1 P1 ps2 -> PML.ps_bcap ps2 mod 2 = 0.

Lemma room_th : forall j pst w' c', (if isbuf then PSYJU.WCONTBY I eg f j pst c' else PSYJU.WCONTY I eg f j pst w' c') -> PMRN.SIq c' ->
  PB6WU.roomW PMR.the_rm f inp (w', [], c') eg pst.
Proof.
  intros j pst w' c' H SI. unfold PB6WU.roomW, inp.
  assert (Hcase : isbuf = true \/ isbuf = false) by (case isbuf; auto).
  destruct Hcase as [Hb|Hb]; rewrite Hb in H |- *; exact (proj2 H SI).
Qed.
Lemma ptw_th : forall j pst w' c' eg' (M2 : mem) ps2 code, (if isbuf then PSYJU.WCONTBY I eg f j pst c' else PSYJU.WCONTY I eg f j pst w' c') ->
  PB6W.expostW PMR.the_rm f inp (w', [], c') eg pst M2 P ps2 code eg' -> (code = 0 -> snd (PSA.wincells (PML.ps_win ps2)) = wend) ->
  PSIU.PTW I eg' j ps2 code M2.
Proof.
  intros j pst w' c' eg' M2 ps2 code H EX HS. unfold PB6W.expostW, inp in EX.
  assert (Hcase : isbuf = true \/ isbuf = false) by (case isbuf; auto).
  destruct Hcase as [Hb|Hb]; rewrite Hb in H, EX; cbv beta iota zeta in EX; destruct EX as (Ec & Ees & Epay & Eok); destruct H as [HW _];
    (apply (HW eg' M2 ps2 code); [exact Ec | first [left; split; [exact Ees | exact Epay] | split; [exact Ees | exact Epay]] |]);
    intros C0; destruct (Eok C0) as (A & B & _); (split; [exact A | split; [exact B | exact (HS C0)]]).
Qed.
Lemma pt_leafx : forall ereg i c k ps1 j cj ci pv lv pe ce d cls,
  is_leaf i c k ps1 (CC.TOther CPC) -> CH2.ret_of G.RETS i k = Some j -> nth_error G.CPS j = Some cj -> SR.ps_pc ps1 = CPC -> PSM5.ng_of CPC = 5%nat ->
  PBX.ptrans_chkx GT.NF G.HDECL Eb 0 Pb 0 CSCR Vb LIT_LO ereg c ps1 cj (nth i G.BLS []) (nth j G.BLS []) = Some ci ->
  PSM2.ldelta i c ps1 = Some (pv, lv, pe, ce, d) -> PSM6.dclass i c ps1 pv lv d = Some cls -> kind_of j = KPt -> PSM2.rng_is (SR.ps_cells ps1) (PB4.pv_more pv) 1 = true ->
  PB.has (SR.ps_cells ps1) (KWord (SA Vb 0) 8 (ELit PML.VT_VISITOR)) = true -> PB.has (SR.ps_cells ps1) (KWord (SA Eb 0) 4 (ELit 0)) = true ->
  (forall E1 E' R' (M1 M' : mem) model1 pst, env_agree GT.NF E0 E' -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' -> regs_ok E' (CA.ps_reglist ps1) R' ->
     HAMB i E1 M' model1 -> XI i E1 M1 -> SIM i E1 M1 -> src_ok i pv lv d cls E1 E' M' pst ->
     exists (w' : list Z) (c' : PMR.ctrl),
     (PMW.win_bytes M' pst w' /\ PMR.rm_match c' M' P pst /\ (if isbuf then PSYJU.WCONTBY I eg f j pst c' else PSYJU.WCONTY I eg f j pst w' c')) /\
     Args R' M' P V E pst [] /\ PAin M' P pst /\ WFin pst /\ BBin pst B /\
     forall R2 (M2 : mem) ps2 code E2, PAout pst M2 P ps2 -> PML.wf_ps ps2 -> (code <> 0 -> PML.ps_more ps2 = false) -> Rel pst ps2 code R2 ->
        env_agree (CC.cp_nx cj - APC.NCS - 5) E' E2 -> ev E2 (CC.cp_nx cj - APC.NCS + 4) = getr R2 10%bv -> (code = 0 -> PMS.not_retreated pst ps2) /\ post_ok j ps2 code E2 M2) ->
  LEAFOKV i c ps1.
Proof.
  intros ereg i c k ps1 j cj ci pv lv pe ce d cls IL Hret Hcj Hpc Hng Hchk Hld Hdc Hkj Hmore Hvis Hec USER.
  pose proof (PB6WU.gbxw_EU L HI PMR.the_rm f MIn inp WFin BBin PAin PAout CPC CSCR Args Rel CALLEE) as CE.
  pose proof (CH2.leaves_all_sound G.CPS G.TAGS ptx_chk ptx_ok i c k ps1 (CC.TOther CPC) IL) as PX.
  unfold ptx_chk in PX. cbv beta iota in PX. rewrite Hng in PX. cbn [Nat.eqb] in PX. rewrite Hret in PX. cbv beta iota in PX.
  apply andb_prop in PX as [PX PBL]. apply andb_prop in PX as [PNX PLOOP]. apply Nat.leb_le in PNX.
  assert (Hcutj : PSM2.cutn j = cj) by (unfold PSM2.cutn; apply nth_error_nth; exact Hcj).
  rewrite Hcutj in PNX.
  refine (PB6WU.ptrans_leaf_okxwU L HI HIok LAY GT.NF E0 M model LBo sp G.HDECL W G.BLS (PSIU.Cred I) (PSIU.XIv I)
    (PSIU.STKF I) PSIU.SCRP PSIU.NF32 (PSIU.U2 I) (PSIU.TP0 I) (PSIU.W_OK I) (PSIU.CRS_OK I) (PSIU.WRS_OK I) (PSIU.IMG_OK I)
    G.CPS G.TAGS G.RETS K (PSIU.iHKnil I) (PSIU.DEF0 I) Eb 0 ltac:(vm_compute; reflexivity) E (PSFU.EADDR I) g (PSIU.iHG I)
    Pb 0 ltac:(vm_compute; reflexivity) P PADDR V S2 (PSIU.iOBJS I) WPAR_in (PSIU.W_ENC I) Vb ltac:(vm_compute; reflexivity) VADDR S2LT S2ADDR
    ltac:(vm_compute; reflexivity) CPC CSCR WFin BBin _ _ _ _ _ _ _ CE (fun _ => PAOUT_CAP) B (PSIU.ikx I) (PSIU.ibxu I) (PSIU.iHkx I) (PSIU.iHbxu0 I)
    LIT_LO ereg i c k ps1 j cj ci eg M0c eq_refl OKV IL Hret Hcj Hpc Hchk _).
  intros E1 E' R' M1 M' model1 cr Hag0 Hsr Hnx Hag LF HR HAV XIV HH HC.
  destruct XIV as (HXI & HXN & HSIM).
  destruct (pt_src i c k ps1 CPC pv lv pe ce d cls IL Hld Hdc Hmore E1 E' R' M1 M' model1 Hag0 Hag LF HAV HXI) as (pst & SRC).
  pose proof SRC as (HPA & HWFP & HBBP & HMORE & HST & HNST & HWIN & HWR & HWP & HADV & HDEN & HLS & HXS & _).
  destruct (USER E1 E' R' M1 M' model1 pst Hag0 Hag LF HR HAV HXI HSIM SRC) as (w' & c' & (HWB & HRM & HWC) & HARGS & HPAIN & HWFIN & HBBIN & UPOST).
  pose proof (PSYJU.siq_of_match c' M' P pst HRM HWFP HMORE) as SIc.
  assert (HAV' : HAMB i E1 M' model1) by exact HAV.
  assert (HXN' : PSIU.xinv I M' eg) by (eapply PSBU.xinv_leaf; eassumption).
  destruct HXN' as (HINV & HLIT).
  assert (HK : know_ok RSEGS E' M' (SR.ps_cells ps1)) by (first [exact (PSBU.leaf_know I c ps1 E' R' M1 M' LF) | exact (PSBU.leaf_know I eg c ps1 E' R' M1 M' LF) | exact (PSBU.leaf_know I eg M0c c ps1 E' R' M1 M' LF) | exact (PSBU.leaf_know I eg M0c OKV c ps1 E' R' M1 M' LF)]).
  exists (w', [], c'), pst. split.
  { rewrite (CH2.den_agree (CC.cp_nx c) E1 E' (nth i G.BLS []) Hag PBL). exact HDEN. }
  split.
  { split; [exact (conj HARGS (conj HWB (MIN _ _ _ _ HRM)))|].
    split; [exact HPAIN|]. split; [exact HWFIN|].
    split.
    { apply (win_ok_eq M' pst (PML.PS 0 0 0 true true 0 [] 0 0 0 0 [] (PB4.win_of (uv E' (PB4.pv_wptr lv)) wend))); [exact HWIN|].
      assert (HDW : L5.defined M' seg wlen) by (eapply PSXU.win_def; eassumption).
      eapply PSXU.win_ok_of; eassumption. }
    split; [exact HBBIN|].
    split; [exact (proj1 (proj1 HINV))|].
    split.
    { assert (HDE : L5.defined M' E 16).
      { eapply PSBU.amb_def with (a := E) (n := 16); try eassumption; [exact (proj1 (proj2 (PSIU.iHEC I))) | pose proof (PSIU.OBJR I); lia]. }
      eapply PSXU.ecell0; eassumption. }
    split; [exact HLS|]. split; [exact HINV|]. split; [exact HLIT|].
    split; [exact (PSIU.iSX I pst eg HXS)|].
    split; [exact (proj1 (PSIU.cred_of_blocks I eg i E1 cr pst HDEN (proj1 (proj2 (proj2 (proj2 HWFP))))) HC)|].
    exact (room_th j pst w' c' HWC SIc). }
  intros R2 M2 cr2 ps2 code g' eg' E2 POST Hag2 Hcode Hr10 Hden2 HPRES.
  destruct POST as (Q1 & Q2 & Q3 & Q4 & Q5 & Q6 & Q7 & Q8 & Q9 & Q10 & Q11 & Q12 & Q13 & Q14).
  assert (Hag2' : env_agree (CC.cp_nx cj - APC.NCS - 5) E' E2) by (rewrite <- Hnx; exact Hag2).
  assert (Hr10' : ev E2 (CC.cp_nx cj - APC.NCS + 4) = getr R2 10%bv)
    by (replace (CC.cp_nx cj - APC.NCS + 4)%nat with (CH2.ci_nx ci + 9)%nat by lia; exact Hr10).
  destruct (UPOST R2 M2 ps2 code E2 Q1 Q2 Q6 Q13 Hag2' Hr10') as (HNR & HPOK).
  cbv zeta in HPOK. destruct HPOK as (cw & PA2 & CUR & SKIP & OK0). rewrite Hcutj in CUR.
  split.
  - split; [|split].
    + unfold PSIU.XI. split.
      { eapply PSFU.hpres_def; [exact HPRES | eapply PSBU.grows_def; [exact (CC.lf_grows _ _ _ _ _ _ _ LF) | exact (proj1 HXI)] | |];
          pose proof (PSIU.STKF I); lia. }
      split.
      { intros _. destruct (Nat.eq_dec i 0) as [Hi0|Hi0].
        - subst i. exact (st0_entry c k ps1 CPC j E' R' M1 M' IL Hng Hret Hkj Hag0 LF).
        - exact (proj1 (proj2 HXI) Hi0). }
      split.
      { intros Hl. apply (proj1 (proj2 (proj2 HXI))). destruct (PSM2.in_loop i); [reflexivity|]. rewrite Hl in PLOOP. discriminate PLOOP. }
      split; [unfold PSIU.XDEP; rewrite Hkj; exact Logic.I|].
      rewrite Hkj. unfold PSIU.pt_post. cbv zeta. rewrite Hcutj.
      exists ps2, code, g', cw.
      split; [exact PA2|]. split; [exact Q2|]. split; [exact Q3|]. split; [exact Q4|]. split; [exact Q5|]. split; [exact Q6|].
      split; [exact Q7|]. split; [exact Q8|]. split; [rewrite <- Hnx; exact Hcode|]. split; [exact Hden2|]. split; [exact SKIP|].
      split; [exact CUR|]. split.
      { intros C0. destruct (OK0 C0) as (A1 & A2 & A3 & A4 & A5). split; [exact A1|]. split; [exact A2|]. split; [exact A3|]. split; [exact A4|]. split; [exact A5|]. exact (PSIU.iXS I ps2 eg' (Q11 C0)). }
      exact (ptw_th j pst w' c' eg' M2 ps2 code HWC Q14 (fun C0 => proj1 (proj2 (OK0 C0)))).
    + exact (conj Q9 Q10).
    + unfold PSIU.SIM. rewrite Hkj. exact Logic.I.
  - exact (proj2 (PSIU.cred_of_blocks I eg' j E2 cr2 ps2 Hden2 (proj1 (proj2 (proj2 (proj2 Q2))))) Q12).
Qed.
End PTX.
