(* [comment removed for export] *)
Lemma slack0 : forall j c ps1 pv lv d cj slack pst E1 E' R' (M1 M' : mem) cls, slack = (if PSM2.in_loop j then PSM6.loop_chk c ps1 pv d (CC.cp_nx cj - APC.NCS - 5)%nat else None) ->
  match slack with Some 0 => true | _ => false end = true -> env_agree GT.NF E0 E' -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' -> src_ok 0 pv lv d cls E1 E' M' pst \/ True ->
  PML.ps_win pst = PB4.win_of (uv E' (PB4.pv_wptr lv)) wend -> seg <= uv E' (PB4.pv_wptr lv) <= wend -> uv E' (PB4.pv_wptr lv) = uv E1 (PB4.pv_wptr pv) + PSM2.d_adv d -> 0 <= PSM2.d_adv d <= 1 ->
