Lemma slack_gen : forall j c ps1 pv lv d cj sl pst E1 E' R' (M1 M' : mem), PSM2.in_loop j = true -> Some sl = (if PSM2.in_loop j then PSM6.loop_chk c ps1 pv d (CC.cp_nx cj - APC.NCS - 5)%nat else None) ->
  env_agree GT.NF E0 E' -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' ->
  PML.ps_win pst = PB4.win_of (uv E' (PB4.pv_wptr lv)) wend -> seg <= uv E' (PB4.pv_wptr lv) <= wend -> uv E' (PB4.pv_wptr lv) = uv E1 (PB4.pv_wptr pv) + PSM2.d_adv d -> 0 <= PSM2.d_adv d <= 1 ->
  0 <= sl <= 2 /\ wend <> 0 /\ PML.ps_win pst = Some (uv E' (PB4.pv_wptr lv), wend) /\ ev E1 54 = ev E' 54 /\
